<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Jobs\RestoreHotelBackup;use App\Models\{BackupRun,BackupRestoreRun};use Illuminate\Http\Request;
class RestoreController extends Controller{public function index(Request $r){abort_unless(in_array($r->user()->role,['super_admin','hotel_owner','general_manager'],true),403);$q=BackupRun::where('status','successful');if($r->user()->role!=='super_admin')$q->where('property_id',$r->user()->property_id);return view('admin.restore',['backups'=>$q->latest()->get(),'restores'=>BackupRestoreRun::latest()->limit(30)->get()]);}public function store(Request $r){abort_unless(in_array($r->user()->role,['super_admin','hotel_owner'],true),403);$d=$r->validate(['backup_run_id'=>'required|exists:backup_runs,id','confirmation'=>'required|in:RESTORE']);$backup=BackupRun::findOrFail($d['backup_run_id']);if($r->user()->role!=='super_admin')abort_unless((int)$backup->property_id===(int)$r->user()->property_id,403);$dryRun=$r->boolean('dry_run',true);if(!$dryRun&&$backup->type!=='database')return back()->withErrors(['backup_run_id'=>'Live restore is currently limited to database-only backups. Files/full archive contents are not restored by this worker; run a dry-run only until file restoration is implemented and tested.']);$run=BackupRestoreRun::create(['property_id'=>$backup->property_id,'backup_run_id'=>$backup->id,'requested_by'=>$r->user()->id,'dry_run'=>$dryRun,'status'=>'queued']);RestoreHotelBackup::dispatch($run->id)->onQueue('backups');return back()->with('success',$run->dry_run?'Restore dry-run queued.':'LIVE DATABASE RESTORE queued. Keep the application in maintenance mode until verified.');}}
